import { useEffect, useRef, useState, useSyncExternalStore, type ReactNode } from 'react';
import { Play } from '@gntik-ai/icons';
import { FlowCanvas, useFlowState, type FlowNode, type FlowNodeData } from '@gntik-ai/flow';
import { Button, ResizablePanel, ResizablePanelGroup, ResizeHandle, cn } from '@gntik-ai/ui';
import {
  builderConsole,
  builderEdges,
  builderNodes,
  builderPalette,
  type ConsoleEntry,
  type FlowEdge,
  type PaletteItem,
} from './fixtures';
import { NodeInspector, NodePalette, RunConsole } from './parts';

export type { ConsoleEntry, FlowEdge, PaletteItem } from './fixtures';
/** Graph types re-exported so apps can type nodes without depending on @gntik-ai/flow. */
export type { FlowNode, FlowNodeData, FlowNodeKind, FlowTone } from '@gntik-ai/flow';

export interface FlowBuilderProps {
  title?: string;
  nodes?: FlowNode[];
  edges?: FlowEdge[];
  palette?: PaletteItem[];
  /**
   * Console output (controlled). Run and Clear then report the next list through
   * `onConsoleChange` instead of updating it internally.
   */
  consoleEntries?: ConsoleEntry[];
  /** Initial console output (uncontrolled). Defaults to the sample entries. */
  defaultConsoleEntries?: ConsoleEntry[];
  /** Called with the next console list after a run appends to it or it is cleared. */
  onConsoleChange?: (entries: ConsoleEntry[]) => void;
  /** Called when the console's Clear button is pressed. */
  onConsoleClear?: () => void;
  /** Heading level of the builder title (default h2); panel titles use the next level. */
  titleAs?: 'h2' | 'h3' | 'h4';
  /** Total height of the builder on wide screens (px). */
  height?: number;
  /**
   * Called with the current graph when Run is pressed. Return console entries (or a promise
   * of them) to log the real run; return nothing to log a simulated run. While a returned
   * promise is pending the Run button shows a loading state; a rejection is logged as an error.
   */
  onRun?: (graph: { nodes: FlowNode[]; edges: FlowEdge[] }) => FlowRunResult | Promise<FlowRunResult>;
  className?: string;
}

/** What `onRun` may return: entries to append, or nothing for the simulated run. */
export type FlowRunResult = ConsoleEntry[] | void | undefined;

const WIDE_QUERY = '(min-width: 768px)';

function subscribeWide(onChange: () => void) {
  if (typeof window === 'undefined' || !window.matchMedia) return () => {};
  const mql = window.matchMedia(WIDE_QUERY);
  mql.addEventListener?.('change', onChange);
  return () => mql.removeEventListener?.('change', onChange);
}

function useIsWide() {
  return useSyncExternalStore(
    subscribeWide,
    () => (typeof window !== 'undefined' && window.matchMedia ? window.matchMedia(WIDE_QUERY).matches : true),
    () => true,
  );
}

function clock() {
  return new Date().toLocaleTimeString('en-GB', { hour12: false });
}

/**
 * Visual flow builder: node palette, brand React Flow canvas (drag, connect, zoom/pan),
 * inspector for the selected node and a run console, in resizable panels. On small screens
 * the panels stack.
 */
export function FlowBuilder({
  title = 'Untitled flow',
  nodes: initialNodes = builderNodes,
  edges: initialEdges = builderEdges,
  palette = builderPalette,
  consoleEntries,
  defaultConsoleEntries = builderConsole,
  onConsoleChange,
  onConsoleClear,
  titleAs: TitleTag = 'h2',
  height = 600,
  onRun,
  className,
}: FlowBuilderProps) {
  const wide = useIsWide();
  const panelAs = TitleTag === 'h2' ? 'h3' : TitleTag === 'h3' ? 'h4' : 'h5';
  const { nodes, edges, setNodes, setEdges, onNodesChange, onEdgesChange, onConnect } = useFlowState<FlowNode, FlowEdge>(
    initialNodes,
    initialEdges,
  );
  const [innerLog, setInnerLog] = useState<ConsoleEntry[]>(defaultConsoleEntries);
  const log = consoleEntries ?? innerLog;
  const latestLog = useRef(log);
  useEffect(() => {
    latestLog.current = log;
  });
  const [running, setRunning] = useState(false);
  const seq = useRef(0);
  const runs = useRef(0);
  const selected = nodes.find((n) => n.selected);

  const addNode = (item: PaletteItem) => {
    seq.current += 1;
    const id = `${item.kind}-${seq.current}`;
    const right = nodes.reduce((max, n) => Math.max(max, n.position.x), -256);
    const slim = item.kind === 'trigger' || item.kind === 'router';
    const node: FlowNode = {
      id,
      type: item.kind,
      position: { x: right + 256, y: 112 + (seq.current % 3) * 32 },
      width: 208,
      height: slim ? 56 : 90,
      selected: true,
      data: { title: `New ${item.title.toLowerCase()}`, subtitle: item.description },
    };
    setNodes((ns) => [...ns.map((n) => (n.selected ? { ...n, selected: false } : n)), node]);
  };

  const updateNode = (id: string, patch: Partial<FlowNodeData>) =>
    setNodes((ns) => ns.map((n) => (n.id === id ? { ...n, data: { ...n.data, ...patch } } : n)));

  const deleteNode = (id: string) => {
    setNodes((ns) => ns.filter((n) => n.id !== id));
    setEdges((es) => es.filter((e) => e.source !== id && e.target !== id));
  };

  const commitLog = (next: ConsoleEntry[]) => {
    latestLog.current = next;
    if (consoleEntries === undefined) setInnerLog(next);
    onConsoleChange?.(next);
  };

  const simulate = (n: number): ConsoleEntry[] => {
    const ordered = [...nodes].sort((a, b) => a.position.x - b.position.x || a.position.y - b.position.y);
    const t = clock();
    return [
      { id: `run-${n}-start`, time: t, level: 'info', message: `Run #${n} started · ${nodes.length} nodes` },
      ...ordered.map<ConsoleEntry>((node, i) => ({
        id: `run-${n}-${node.id}`,
        time: t,
        level: node.data.tone === 'failed' ? 'error' : node.data.tone === 'degraded' ? 'warn' : 'success',
        message: `${node.data.title} ${node.data.tone === 'failed' ? 'failed' : 'completed'} in ${40 + ((i * 37) % 160)}ms`,
      })),
      { id: `run-${n}-end`, time: t, level: 'info', message: `Run #${n} finished` },
    ];
  };

  const run = async () => {
    runs.current += 1;
    const n = runs.current;
    const result = onRun?.({ nodes, edges });
    let added: ConsoleEntry[];
    if (result instanceof Promise) {
      setRunning(true);
      try {
        added = (await result) ?? simulate(n);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        added = [{ id: `run-${n}-error`, time: clock(), level: 'error', message: `Run #${n} failed: ${message}` }];
      } finally {
        setRunning(false);
      }
    } else {
      added = result ?? simulate(n);
    }
    commitLog([...latestLog.current, ...added]);
  };

  const clearLog = () => {
    onConsoleClear?.();
    commitLog([]);
  };

  const canvas = (h: number | string) => (
    <FlowCanvas<FlowNode, FlowEdge>
      aria-label={`${title} canvas`}
      height={h}
      nodes={nodes}
      edges={edges}
      onNodesChange={onNodesChange}
      onEdgesChange={onEdgesChange}
      onConnect={onConnect}
      showMiniMap={wide}
    />
  );
  const palettePanel = <NodePalette items={palette} onAdd={addNode} titleAs={panelAs} />;
  const inspector = <NodeInspector node={selected} onChange={updateNode} onDelete={deleteNode} titleAs={panelAs} />;
  const consolePanel = <RunConsole entries={log} onClear={clearLog} titleAs={panelAs} />;

  let body: ReactNode;
  if (wide) {
    body = (
      <ResizablePanelGroup direction="vertical" style={{ height }}>
        <ResizablePanel defaultSize={72} minSize={40}>
          <ResizablePanelGroup className="h-full">
            <ResizablePanel defaultSize={18} minSize={12} maxSize={32} collapsible>
              {palettePanel}
            </ResizablePanel>
            <ResizeHandle aria-label="Resize node palette" />
            <ResizablePanel defaultSize={58} minSize={30}>
              {canvas('100%')}
            </ResizablePanel>
            <ResizeHandle aria-label="Resize inspector" />
            <ResizablePanel defaultSize={24} minSize={16} maxSize={40} collapsible>
              {inspector}
            </ResizablePanel>
          </ResizablePanelGroup>
        </ResizablePanel>
        <ResizeHandle aria-label="Resize run console" />
        <ResizablePanel defaultSize={28} minSize={12} collapsible>
          {consolePanel}
        </ResizablePanel>
      </ResizablePanelGroup>
    );
  } else {
    body = (
      <div className="flex flex-col divide-y divide-border">
        <div className="max-h-56">{palettePanel}</div>
        {canvas(360)}
        <div>{inspector}</div>
        <div className="h-48">{consolePanel}</div>
      </div>
    );
  }

  return (
    <section aria-label={title} className={cn('overflow-hidden rounded-lg border border-border bg-card shadow-sm', className)}>
      <header className="flex items-center justify-between gap-3 border-b border-border bg-secondary/35 px-3 py-2">
        <div className="min-w-0">
          <TitleTag className="truncate text-[13.5px] font-semibold text-foreground">{title}</TitleTag>
          <p className="font-mono text-[11px] text-muted-foreground">
            {nodes.length} nodes · {edges.length} edges
          </p>
        </div>
        <Button size="sm" icon={Play} loading={running} onClick={() => void run()}>
          Run
        </Button>
      </header>
      {body}
    </section>
  );
}

import type { FlowCanvasProps, FlowNode, FlowNodeKind } from '@gntik-ai/flow';

/** React Flow edge, as FlowCanvas takes it. */
export type FlowEdge = NonNullable<FlowCanvasProps['edges']>[number];

export interface PaletteItem {
  kind: FlowNodeKind;
  /** Default title of a node created from this item. */
  title: string;
  description: string;
}

export interface ConsoleEntry {
  id: string;
  /** Display time, e.g. "10:42:07". */
  time: string;
  level: 'info' | 'success' | 'warn' | 'error';
  message: string;
}

const CARD = { width: 208, height: 90 } as const;
const SLIM = { width: 208, height: 56 } as const;

/** Neutral starter flow: webhook → validate → route → notify / store. */
export const builderNodes: FlowNode[] = [
  { id: 'webhook', type: 'trigger', position: { x: 0, y: 112 }, ...SLIM, data: { title: 'Webhook', subtitle: 'POST /v1/orders' } },
  { id: 'validate', type: 'step', position: { x: 256, y: 96 }, ...CARD, data: { title: 'Validate payload', subtitle: 'schema check', meta: 'v1.4', tone: 'done' } },
  { id: 'route', type: 'router', position: { x: 512, y: 112 }, ...SLIM, data: { title: 'Route by region', subtitle: '2 branches' } },
  { id: 'notify', type: 'output', position: { x: 768, y: 16 }, ...CARD, data: { title: 'Notify team', subtitle: 'email digest' } },
  { id: 'store', type: 'output', position: { x: 768, y: 192 }, ...CARD, data: { title: 'Store record', subtitle: 'orders table' } },
];

export const builderEdges: FlowEdge[] = [
  { id: 'e-webhook-validate', source: 'webhook', target: 'validate', animated: true },
  { id: 'e-validate-route', source: 'validate', target: 'route' },
  { id: 'e-route-notify', source: 'route', target: 'notify', label: 'eu' },
  { id: 'e-route-store', source: 'route', target: 'store', label: 'other' },
];

export const builderPalette: PaletteItem[] = [
  { kind: 'trigger', title: 'Trigger', description: 'Starts the flow on an event' },
  { kind: 'step', title: 'Step', description: 'Processes or transforms data' },
  { kind: 'router', title: 'Router', description: 'Branches on a condition' },
  { kind: 'output', title: 'Output', description: 'Sends the final result' },
];

export const builderConsole: ConsoleEntry[] = [
  { id: 'c1', time: '10:41:58', level: 'info', message: 'Flow loaded · 5 nodes, 4 edges' },
  { id: 'c2', time: '10:42:01', level: 'success', message: 'Validation passed' },
];

import { useId } from 'react';
import { MousePointerClick, Plus, Trash2 } from '@gntik-ai/icons';
import { FLOW_TONES, KIND_CHIP, KindGlyph, type FlowNode, type FlowNodeData, type FlowTone } from '@gntik-ai/flow';
import { Button, Field, FieldLabel, Input, SimpleSelect, cn } from '@gntik-ai/ui';
import type { ConsoleEntry, PaletteItem } from './fixtures';

/** Heading level of a panel title (one below the builder's title). */
export type PanelHeading = 'h3' | 'h4' | 'h5';

const panelTitle = 'px-3 pt-3 pb-2 font-mono text-[10.5px] font-medium tracking-[0.12em] text-muted-foreground uppercase';

export interface NodePaletteProps {
  items: PaletteItem[];
  onAdd: (item: PaletteItem) => void;
  /** Heading level of the panel title (default h3). */
  titleAs?: PanelHeading;
}

/** Left rail: node kinds to add to the canvas. */
export function NodePalette({ items, onAdd, titleAs: TitleTag = 'h3' }: NodePaletteProps) {
  const titleId = useId();
  return (
    <div className="flex h-full min-h-0 flex-col bg-card">
      <TitleTag id={titleId} className={panelTitle}>
        Nodes
      </TitleTag>
      <ul aria-labelledby={titleId} className="flex-1 overflow-y-auto px-2 pb-2">
        {items.map((item) => (
          <li key={item.kind + item.title}>
            <button
              type="button"
              onClick={() => onAdd(item)}
              aria-label={`Add ${item.title}`}
              title={item.description}
              className="group flex w-full items-center gap-2.5 rounded-md px-2 py-2 text-start hover:bg-secondary/70 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring"
            >
              <span className={cn('grid size-7 shrink-0 place-items-center rounded-md', KIND_CHIP[item.kind])}>
                <KindGlyph kind={item.kind} size={14} />
              </span>
              <span className="min-w-0 flex-1">
                <span className="block text-[12.5px] font-medium text-foreground">{item.title}</span>
                <span className="block truncate text-[11px] text-muted-foreground">{item.description}</span>
              </span>
              <Plus size={14} aria-hidden className="shrink-0 text-muted-foreground group-hover:text-foreground" />
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

const TONE_ITEMS = [
  { value: 'none', label: 'No status' },
  ...(Object.keys(FLOW_TONES) as FlowTone[]).map((t) => ({ value: t, label: FLOW_TONES[t].label })),
];

export interface NodeInspectorProps {
  node: FlowNode | undefined;
  onChange: (id: string, patch: Partial<FlowNodeData>) => void;
  onDelete: (id: string) => void;
  /** Heading level of the panel title (default h3). */
  titleAs?: PanelHeading;
}

/** Right rail: the selected node's editable fields. */
export function NodeInspector({ node, onChange, onDelete, titleAs: TitleTag = 'h3' }: NodeInspectorProps) {
  const titleId = useId();
  return (
    <div className="flex h-full min-h-0 flex-col bg-card">
      <TitleTag id={titleId} className={panelTitle}>
        Inspector
      </TitleTag>
      {node ? (
        <form
          aria-labelledby={titleId}
          onSubmit={(e) => e.preventDefault()}
          className="flex flex-1 flex-col gap-3 overflow-y-auto px-3 pb-3"
        >
          <p className="flex items-center gap-2 text-[12px] text-muted-foreground">
            <span className={cn('grid size-5 place-items-center rounded', KIND_CHIP[node.type ?? 'step'])}>
              <KindGlyph kind={node.type ?? 'step'} size={11} />
            </span>
            <span className="capitalize">{node.type}</span>
            <span className="font-mono text-[11px]">· {node.id}</span>
          </p>
          <Field>
            <FieldLabel>Title</FieldLabel>
            <Input size="sm" value={node.data.title} onValueChange={(v) => onChange(node.id, { title: String(v) })} />
          </Field>
          <Field>
            <FieldLabel>Subtitle</FieldLabel>
            <Input size="sm" value={node.data.subtitle ?? ''} onValueChange={(v) => onChange(node.id, { subtitle: String(v) || undefined })} />
          </Field>
          <Field>
            <FieldLabel>Meta</FieldLabel>
            <Input size="sm" value={node.data.meta ?? ''} onValueChange={(v) => onChange(node.id, { meta: String(v) || undefined })} />
          </Field>
          <SimpleSelect
            label="Status"
            size="sm"
            items={TONE_ITEMS}
            value={node.data.tone ?? 'none'}
            onValueChange={(v) => onChange(node.id, { tone: v && v !== 'none' ? (v as FlowTone) : undefined })}
          />
          <Button variant="ghost" size="sm" icon={Trash2} onClick={() => onDelete(node.id)} className="mt-auto self-start">
            Delete node
          </Button>
        </form>
      ) : (
        <div className="flex flex-1 flex-col items-center justify-center gap-2 px-4 pb-6 text-center">
          <MousePointerClick size={18} aria-hidden className="text-muted-foreground" />
          <p className="text-[12.5px] text-muted-foreground">Select a node to edit its fields.</p>
        </div>
      )}
    </div>
  );
}

const CONSOLE_LEVEL: Record<ConsoleEntry['level'], string> = {
  info: 'text-muted-foreground',
  success: 'text-success-text',
  warn: 'text-warning-text',
  error: 'text-destructive-text',
};

export interface RunConsoleProps {
  entries: ConsoleEntry[];
  onClear: () => void;
  /** Heading level of the panel title (default h3). */
  titleAs?: PanelHeading;
}

/** Bottom panel: run output (role="log"). */
export function RunConsole({ entries, onClear, titleAs: TitleTag = 'h3' }: RunConsoleProps) {
  return (
    <div className="flex h-full min-h-0 flex-col bg-card">
      <div className="flex items-center justify-between border-b border-border pe-2">
        <TitleTag className={cn(panelTitle, 'pb-2')}>Run console</TitleTag>
        <Button variant="ghost" size="sm" onClick={onClear} disabled={entries.length === 0} className="h-7">
          Clear
        </Button>
      </div>
      <div role="log" aria-label="Run console" tabIndex={0} className="flex-1 overflow-y-auto px-3 py-2 font-mono text-[11.5px] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-focus-ring">
        {entries.length === 0 ? (
          <p className="font-sans text-[12.5px] text-muted-foreground">No output yet. Run the flow to see its steps.</p>
        ) : (
          entries.map((e) => (
            <p key={e.id} className="flex gap-3 py-0.5">
              <span className="shrink-0 text-muted-foreground tabular-nums">{e.time}</span>
              <span className={cn('w-14 shrink-0 uppercase', CONSOLE_LEVEL[e.level])}>{e.level}</span>
              <span className="min-w-0 text-foreground">{e.message}</span>
            </p>
          ))
        )}
      </div>
    </div>
  );
}
